398	\begin{lemma}[Close strategies have close values; Fact 4.32 in \cite{Natarajan2018NEEXP}]\label{lem:close-strategies-have-close-values}
399		\uses{def:strategy-distance, def:tensor-product-value, def:projective-strategy-general}
