28	\begin{definition}[Bracket notation for post-processed measurements]\label{def:bracket}
29		\uses{def:povm-conventions, def:post-processing}
30		Let $\mathcal A$ and $\mathcal B$ be finite sets, let $\{M^x_a\}_{a \in \mathcal A}$ be a family of POVMs indexed by $x \in \mathcal X$, and let $f \colon \mathcal A \to \mathcal B$ be an arbitrary function. We write $\bigl\{ M^x_{[f(\cdot)=b]} \bigr\}$ for the POVM derived from $\{M^x_a\}$ by applying the function $f$ to the outcome before returning it:
31		\[
32			M^x_{[f(\cdot)=b]} = \sum_{a\,:\,f(a)=b} M^x_a\,,
33		\]
34		and $M^x_{[f(\cdot)=b]} = 0$ when $b$ is not in the image of $f$. When the outcome $a$ has a natural interpretation as a tuple $(a_1,\dots,a_k)$, we also write, for $i \in \{1,\dots,k\}$,
35		\[
36			M^x_{[a_i=b]} = \sum_{(a_1,\dots,a_k)\,:\,a_i=b} M^x_{(a_1,\dots,a_k)}\,.
37		\]
38		For each fixed $x$ this is the post-processing operation of Definition~\ref{def:post-processing}.
39	\end{definition}
